import{_ as e,c as a,o,ae as s}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Country and State","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/countries/index.md","filePath":"api/rest-api/shop/countries/index.md"}'),r={name:"api/rest-api/shop/countries/index.md"};function n(d,t,i,c,h,l){return o(),a("div",null,t[0]||(t[0]=[s('<h1 id="country-and-state" tabindex="-1">Country and State <a class="header-anchor" href="#country-and-state" aria-label="Permalink to &quot;Country and State&quot;">​</a></h1><p>The Country and State menu provides the reference data behind address forms — the list of countries the store accepts and the states / regions within each country. Use it to populate country and state dropdowns at registration, address creation and checkout.</p><h2 id="countries-and-states" tabindex="-1">Countries and States <a class="header-anchor" href="#countries-and-states" aria-label="Permalink to &quot;Countries and States&quot;">​</a></h2><ul><li><strong>Countries</strong> returns the full country list — 254 rows, each with its <code>code</code>, <code>name</code>, and its states inlined under <code>states</code>.</li><li><strong>Country states</strong> returns state and region rows. The states for one country are already inside that country&#39;s row, so this endpoint is only needed when you want state records on their own.</li></ul><h2 id="reading-the-states-of-one-country" tabindex="-1">Reading the States of One Country <a class="header-anchor" href="#reading-the-states-of-one-country" aria-label="Permalink to &quot;Reading the States of One Country&quot;">​</a></h2><p>There are two paths, and only one of them filters:</p><table tabindex="0"><thead><tr><th>Path</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>GET /api/shop/countries/{countryId}/states</code></td><td>Returns just that country&#39;s states.</td></tr><tr><td><code>GET /api/shop/country-states</code></td><td>The whole 586-row collection, paginated. <strong>It takes no filter</strong> — <code>?country_id=</code>, <code>?countryCode=</code> and the like are accepted by the URL and ignored, so every call returns the same first page.</td></tr></tbody></table><p>For an address form, the simplest route is to read the country list once: each row already carries its <code>states</code>, so a country/state picker needs a single request rather than one per country.</p><h2 id="paging-through-the-full-lists" tabindex="-1">Paging Through the Full Lists <a class="header-anchor" href="#paging-through-the-full-lists" aria-label="Permalink to &quot;Paging Through the Full Lists&quot;">​</a></h2><p>Both collections default to 10 rows per page and cap at 50, with totals in the <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, and <code>X-Total-Pages</code> headers. Left at the default, the country list takes 26 requests to walk — raise <code>per_page</code> to 50 and cache the result, since this is static reference data that only changes when the store&#39;s country set is edited.</p><h2 id="localisation" tabindex="-1">Localisation <a class="header-anchor" href="#localisation" aria-label="Permalink to &quot;Localisation&quot;">​</a></h2><p>Country and state names follow the request locale through <code>X-Locale</code>; each row also carries a <code>translations</code> array holding every stored language, so a multilingual client can cache them all in one pass. Match a shopper&#39;s saved address on <code>code</code>, never on the display name — the name changes with the locale, the code does not.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/countries/get-countries.html">Countries</a></td><td><code>GET /api/shop/countries</code></td><td>List the available countries.</td></tr><tr><td><a href="/api/rest-api/shop/countries/get-country-states.html">Country States</a></td><td><code>GET /api/shop/country-states</code></td><td>Flat, unfiltered collection of state rows.</td></tr></tbody></table><p>These codes are what the rest of the API expects: address create and update, and the checkout address step, all store <code>country</code> and <code>state</code> as codes taken from here.</p><p>All Country and State endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',16)]))}const y=e(r,[["render",n]]);export{p as __pageData,y as default};
